  1→/**
  2→ * prism-memory.ts — M3-A 持久大脑存取接口
  3→ *
  4→ * 配置驱动的分类注册表 + 文件系统持久化（md 条目，人可读可手改）。
  5→ * 注入(M3-B) / 沉淀(M3-C) 不在本模块，仅提供 load / append 原语。
  6→ */
  7→import * as fs from 'fs';
  8→import * as path from 'path';
  9→import { fileURLToPath } from 'url';
 10→
 11→export type MemoryCategory = string;
 12→
 13→/**
 14→ * 数据源标识（DR-45 §一 / WT-040）：用于按数据源筛选注入。
 15→ * - `perfetto`  — Perfetto trace 分析
 16→ * - `unity`     — Unity profiler 分析
 17→ * - `simpleperf` — simpleperf 分析
 18→ * - `cross-source` — 跨源通用（如"GC.Collect 卡顿判定"任何源都适用）
 19→ * 未设置时视为兼容期旧条目，所有数据源都注入（不排除）。
 20→ */
 21→export type MemoryDataSource = 'perfetto' | 'unity' | 'simpleperf' | 'cross-source';
 22→
 23→/** 合法 dataSource 取值集合（WT-040 硬约束 4：不许自创） */
 24→export const VALID_DATA_SOURCES: readonly MemoryDataSource[] = [
 25→  'perfetto',
 26→  'unity',
 27→  'simpleperf',
 28→  'cross-source',
 29→];
 30→
 31→/** 判断一个 dataSource 字符串是否合法（WT-040） */
 32→export function isValidDataSource(value: string): value is MemoryDataSource {
 33→  return (VALID_DATA_SOURCES as readonly string[]).includes(value);
 34→}
 35→
 36→export interface MemoryEntry {
 37→  id: string;
 38→  category: MemoryCategory;
 39→  content: string;
 40→  source?: string;
 41→  /** 数据源标识（WT-040）：用于按数据源筛选注入；缺省视为兼容期旧条目 */
 42→  dataSource?: MemoryDataSource;
 43→  createdAt: string;
 44→  [k: string]: unknown;
 45→}
 46→
 47→export interface MemoryCategoryConfig {
 48→  name: MemoryCategory;
 49→  dir: string;
 50→  enabled: boolean;
 51→  description: string;
 52→}
 53→
 54→/** 分类注册表：加新类只改这里，不动读写逻辑 */
 55→export const MEMORY_CATEGORIES: MemoryCategoryConfig[] = [
 56→  {
 57→    name: 'priors',
 58→    dir: 'priors',
 59→    enabled: true,
 60→    description: '先验知识（人工种子，如 Unity/AOE 分析知识）',
 61→  },
 62→  {
 63→    name: 'knowledge',
 64→    dir: 'knowledge',
 65→    enabled: true,
 66→    description: '知识回路（run 确认的业务归因 findings）',
 67→  },
 68→  {
 69→    name: 'capabilities',
 70→    dir: 'capabilities',
 71→    enabled: true,
 72→    description: '能力回路（DataRequest 池高频项）',
 73→  },
 74→  {
 75→    name: 'lessons',
 76→    dir: 'lessons',
 77→    enabled: true,
 78→    description: '质量回路（对错教训，依赖金标 BK-4）',
 79→  },
 80→];
 81→
 82→export interface LoadMemoryOptions {
 83→  /** 只加载指定分类；未指定时加载所有 enabled 分类 */
 84→  categories?: MemoryCategory[];
 85→  /** 覆盖默认存储根目录（单测用） */
 86→  root?: string;
 87→}
 88→
 89→export interface AppendMemoryOptions {
 90→  /** 覆盖默认存储根目录（单测用） */
 91→  root?: string;
 92→}
 93→
 94→interface MemoryIndex {
 95→  version: number;
 96→  updatedAt: string;
 97→  categories: Record<string, { count: number; lastUpdated: string | null }>;
 98→}
 99→
100→const MODULE_DIR = path.dirname(fileURLToPath(import.meta.url));
101→const DEFAULT_MEMORY_ROOT = path.join(MODULE_DIR, 'prism-memory');
102→
103→function getMemoryRoot(opts?: { root?: string }): string {
104→  return opts?.root ?? DEFAULT_MEMORY_ROOT;
105→}
106→
107→function getCategoryConfig(name: MemoryCategory): MemoryCategoryConfig | undefined {
108→  return MEMORY_CATEGORIES.find((c) => c.name === name);
109→}
110→
111→function categoryDir(root: string, config: MemoryCategoryConfig): string {
112→  return path.join(root, config.dir);
113→}
114→
115→function ensureCategoryDir(root: string, config: MemoryCategoryConfig): void {
116→  const dir = categoryDir(root, config);
117→  if (!fs.existsSync(dir)) {
118→    fs.mkdirSync(dir, { recursive: true });
119→  }
120→}
121→
122→function parseFrontmatter(raw: string): { meta: Record<string, unknown>; content: string } {
123→  const trimmed = raw.replace(/^\uFEFF/, '').trimStart();
124→  if (!trimmed.startsWith('---')) {
125→    return { meta: {}, content: trimmed };
126→  }
127→  const end = trimmed.indexOf('---', 3);
128→  if (end === -1) {
129→    return { meta: {}, content: trimmed };
130→  }
131→  const header = trimmed.slice(3, end).trim();
132→  const content = trimmed.slice(end + 3).trimStart();
133→  const meta: Record<string, unknown> = {};
134→  for (const line of header.split('\n')) {
135→    const colon = line.indexOf(':');
136→    if (colon === -1) continue;
137→    const key = line.slice(0, colon).trim();
138→    let value: unknown = line.slice(colon + 1).trim();
139→    if (typeof value === 'string' && value.startsWith('"') && value.endsWith('"')) {
140→      value = value.slice(1, -1);
141→    }
142→    meta[key] = value;
143→  }
144→  return { meta, content };
145→}
146→
147→function serializeEntry(entry: MemoryEntry): string {
148→  const lines = [
149→    '---',
150→    `id: ${entry.id}`,
151→    `category: ${entry.category}`,
152→    `createdAt: ${entry.createdAt}`,
153→  ];
154→  if (entry.source) {
155→    lines.push(`source: ${entry.source}`);
156→  }
157→  for (const [key, value] of Object.entries(entry)) {
158→    if (['id', 'category', 'content', 'createdAt', 'source'].includes(key)) continue;
159→    if (value === undefined) continue;
160→    lines.push(`${key}: ${JSON.stringify(value)}`);
161→  }
162→  lines.push('---', '', entry.content);
163→  return lines.join('\n');
164→}
165→
166→function entryFromFile(category: MemoryCategory, filePath: string): MemoryEntry | null {
167→  try {
168→    const raw = fs.readFileSync(filePath, 'utf8');
169→    const { meta, content } = parseFrontmatter(raw);
170→    const id = String(meta.id ?? path.basename(filePath, '.md'));
171→    const createdAt = String(meta.createdAt ?? new Date(0).toISOString());
172→    const source = meta.source !== undefined ? String(meta.source) : undefined;
173→    const entry: MemoryEntry = {
174→      id,
175→      category: String(meta.category ?? category),
176→      content,
177→      createdAt,
178→    };
179→    if (source) entry.source = source;
180→    for (const [key, value] of Object.entries(meta)) {
181→      if (['id', 'category', 'createdAt', 'source'].includes(key)) continue;
182→      entry[key] = value;
183→    }
184→    return entry;
185→  } catch {
186→    return null;
187→  }
188→}
189→
190→function loadEntriesForCategory(
191→  root: string,
192→  config: MemoryCategoryConfig,
193→): MemoryEntry[] {
194→  const dir = categoryDir(root, config);
195→  if (!fs.existsSync(dir)) {
196→    return [];
197→  }
198→  const entries: MemoryEntry[] = [];
199→  for (const name of fs.readdirSync(dir)) {
200→    if (!name.endsWith('.md') || name === 'README.md') continue;
201→    const filePath = path.join(dir, name);
202→    if (!fs.statSync(filePath).isFile()) continue;
203→    const entry = entryFromFile(config.name, filePath);
204→    if (entry) entries.push(entry);
205→  }
206→  entries.sort((a, b) => a.createdAt.localeCompare(b.createdAt));
207→  return entries;
208→}
209→
210→function readIndex(root: string): MemoryIndex {
211→  const indexPath = path.join(root, 'index.json');
212→  if (!fs.existsSync(indexPath)) {
213→    return buildIndexFromDisk(root);
214→  }
215→  try {
216→    const parsed = JSON.parse(fs.readFileSync(indexPath, 'utf8')) as MemoryIndex;
217→    return parsed;
218→  } catch {
219→    return buildIndexFromDisk(root);
220→  }
221→}
222→
223→function buildIndexFromDisk(root: string): MemoryIndex {
224→  const categories: MemoryIndex['categories'] = {};
225→  for (const config of MEMORY_CATEGORIES) {
226→    const entries = loadEntriesForCategory(root, config);
227→    const lastUpdated =
228→      entries.length > 0 ? entries[entries.length - 1]!.createdAt : null;
229→    categories[config.name] = { count: entries.length, lastUpdated };
230→  }
231→  return {
232→    version: 1,
233→    updatedAt: new Date().toISOString(),
234→    categories,
235→  };
236→}
237→
238→function writeIndex(root: string): void {
239→  const index = buildIndexFromDisk(root);
240→  index.updatedAt = new Date().toISOString();
241→  const indexPath = path.join(root, 'index.json');
242→  fs.writeFileSync(indexPath, JSON.stringify(index, null, 2) + '\n', 'utf8');
243→}
244→
245→function resolveCategoriesToLoad(opts?: LoadMemoryOptions): MemoryCategoryConfig[] {
246→  const requested = opts?.categories;
247→  if (requested && requested.length > 0) {
248→    return requested
249→      .map((name) => getCategoryConfig(name))
250→      .filter((c): c is MemoryCategoryConfig => c !== undefined);
251→  }
252→  return MEMORY_CATEGORIES.filter((c) => c.enabled);
253→}
254→
255→/** 读大脑；可按分类筛选、可只读启用的分类 */
256→export function loadMemory(opts?: LoadMemoryOptions): {
257→  entries: MemoryEntry[];
258→  byCategory: Record<string, MemoryEntry[]>;
259→} {
260→  const root = getMemoryRoot(opts);
261→  const configs = resolveCategoriesToLoad(opts);
262→  const byCategory: Record<string, MemoryEntry[]> = {};
263→  const entries: MemoryEntry[] = [];
264→
265→  for (const config of configs) {
266→    const catEntries = loadEntriesForCategory(root, config);
267→    byCategory[config.name] = catEntries;
268→    entries.push(...catEntries);
269→  }
270→
271→  return { entries, byCategory };
272→}
273→
274→/** 追加一条并持久化 */
275→export function appendMemory(
276→  category: MemoryCategory,
277→  entry: Omit<MemoryEntry, 'category' | 'createdAt'> & { createdAt?: string },
278→  opts?: AppendMemoryOptions,
279→): MemoryEntry {
280→  const config = getCategoryConfig(category);
281→  if (!config) {
282→    throw new Error(`Unknown memory category: ${category}`);
283→  }
284→
285→  const root = getMemoryRoot(opts);
286→  ensureCategoryDir(root, config);
287→
288→  const fullEntry: MemoryEntry = {
289→    ...entry,
290→    category,
291→    createdAt: entry.createdAt ?? new Date().toISOString(),
292→  };
293→
294→  const safeId = fullEntry.id.replace(/[^a-zA-Z0-9._-]/g, '_');
295→  const filePath = path.join(categoryDir(root, config), `${safeId}.md`);
296→  fs.writeFileSync(filePath, serializeEntry(fullEntry), 'utf8');
297→  writeIndex(root);
298→
299→  return fullEntry;
300→}
301→
302→/** 读取 index.json 概览（缺文件时从磁盘重建，不抛错） */
303→export function loadMemoryIndex(opts?: { root?: string }): MemoryIndex {
304→  const root = getMemoryRoot(opts);
305→  return readIndex(root);
306→}
307→
308→/**
309→ * 按 source 清除某分类下该来源的所有旧条目（返回删除条数）。
310→ * 用于"整篇重摄入"场景（如先验知识 md 重新清洗）——先清旧、再写新，避免 LLM 切分 id 不稳定导致的重复堆积。
311→ * ⚠️ 仅用于整源覆盖；三回路增量沉淀绝不能用此清空（会丢历史）。
312→ */
313→export function clearBySource(
314→  category: MemoryCategory,
315→  source: string,
316→  opts?: { root?: string },
317→): number {
318→  const config = getCategoryConfig(category);
319→  if (!config) throw new Error(`Unknown memory category: ${category}`);
320→  const root = getMemoryRoot(opts);
321→  const dir = categoryDir(root, config);
322→  if (!fs.existsSync(dir)) return 0;
323→
324→  let removed = 0;
325→  for (const name of fs.readdirSync(dir)) {
326→    if (!name.endsWith('.md') || name === 'README.md') continue;
327→    const filePath = path.join(dir, name);
328→    if (!fs.statSync(filePath).isFile()) continue;
329→    const entry = entryFromFile(config.name, filePath);
330→    if (entry && entry.source === source) {
331→      fs.unlinkSync(filePath);
332→      removed++;
333→    }
334→  }
335→  if (removed > 0) writeIndex(root);
336→  return removed;
337→}
