  1→/**
  2→ * explore-service.ts — Prism Phase-A exploration pipeline (task B4)
  3→ *
  4→ * Spawns the LLM CLI with the explore-prompt, records a ledger of every
  5→ * tool_use / tool_result seen in the stream-json output, then verifies
  6→ * each Finding's evidence against the real calls in that ledger.
  7→ *
  8→ * Key principle (F1): every number in a Finding must trace back to a
  9→ * real tool call; verifyFindings detects fabricated evidence.
 10→ */
 11→
 12→import crypto from 'crypto';
 13→import fs from 'fs';
 14→import path from 'path';
 15→import { spawn } from 'child_process';
 16→import { fileURLToPath } from 'url';
 17→import { resolveCliExecutable, spawnCliProcess, cliUnavailableHint } from '../utils/cli-resolver.js';
 18→import { getConfig } from '../utils/config.js';
 19→import { appendMemory, loadMemory, type MemoryCategory, type MemoryEntry } from './prism-memory.js';
 20→import type { Finding, DataRequest, ExploreResult } from './types.js';
 21→
 22→/** Categories injected at explore startup (M3-B). Adjust here, not inline in formatters. */
 23→export const MEMORY_INJECTION_CATEGORIES: MemoryCategory[] = [
 24→  'priors',
 25→  'knowledge',
 26→  'lessons',
 27→  'capabilities',
 28→];
 29→
 30→/** M3-C: persist run DataRequests into capabilities/ at explore end (default on). */
 31→export const DATA_REQUEST_MEMORY_PERSIST_ENABLED = true;
 32→
 33→/** Max characters for the {{MEMORY_INJECTION}} block (~7KB). */
 34→export const MEMORY_INJECTION_MAX_CHARS = 7000;
 35→
 36→// ─────────────────────────────────────────────
 37→// M3-B: memory injection for explore prompt
 38→// ─────────────────────────────────────────────
 39→
 40→export interface FormatMemoryForPromptOptions {
 41→  /** Override memory root (tests). */
 42→  root?: string;
 43→  /**
 44→   * 数据源筛选（WT-040 / DR-45 §二）：给定后只注入该数据源 + cross-source + 无 dataSource 字段的旧条目。
 45→   * 未给定 → 注入全部（兼容现有行为）。
 46→   */
 47→  dataSource?: 'unity' | 'perfetto' | 'simpleperf';
 48→}
 49→
 50→/**
 51→ * Load persistent brain entries and format as compact reference text for the explore prompt.
 52→ *
 53→ * WT-040: 当 opts.dataSource 给定时，按数据源筛选——只保留该数据源条目 + cross-source 通用条目
 54→ * + 无 dataSource 字段的旧条目（兼容期，避免老条目被过滤导致 explore 退化）。
 55→ */
 56→export function formatMemoryForPrompt(opts?: FormatMemoryForPromptOptions): string {
 57→  const { byCategory } = loadMemory({
 58→    categories: MEMORY_INJECTION_CATEGORIES,
 59→    root: opts?.root,
 60→  });
 61→
 62→  const dataSource = opts?.dataSource;
 63→  const filterByDataSource = (entries: MemoryEntry[]): MemoryEntry[] => {
 64→    if (!dataSource) return entries;
 65→    return entries.filter((e) => {
 66→      // 旧条目无 dataSource 字段 → 包含（兼容期，不排除）
 67→      if (e.dataSource === undefined) return true;
 68→      // 该数据源条目 → 包含
 69→      if (e.dataSource === dataSource) return true;
 70→      // 跨源通用条目 → 包含
 71→      if (e.dataSource === 'cross-source') return true;
 72→      // 其它数据源 → 排除
 73→      return false;
 74→    });
 75→  };
 76→
 77→  // Per-category budget so a large category (e.g. 79 priors) can't starve
 78→  // later categories (e.g. freshly-sedimented capabilities). Split the total
 79→  // budget across categories that actually have entries.
 80→  // WT-040: 先按 dataSource 筛选，再算 activeCats（避免某分类筛完后为空仍占预算）
 81→  const byCategoryFiltered: Record<string, MemoryEntry[]> = {};
 82→  for (const cat of MEMORY_INJECTION_CATEGORIES) {
 83→    byCategoryFiltered[cat] = filterByDataSource(byCategory[cat] ?? []);
 84→  }
 85→  const activeCats = MEMORY_INJECTION_CATEGORIES.filter((c) => byCategoryFiltered[c]?.length);
 86→  if (activeCats.length === 0) return '';
 87→  const perCatBudget = Math.floor(MEMORY_INJECTION_MAX_CHARS / activeCats.length);
 88→
 89→  const blocks: string[] = [];
 90→
 91→  for (const cat of activeCats) {
 92→    const catEntries = byCategoryFiltered[cat]!;
 93→    const catLines: string[] = [`## ${cat} (${catEntries.length})`];
 94→    let catChars = catLines[0].length + 1;
 95→    let catTruncated = false;
 96→    let shown = 0;
 97→
 98→    for (const entry of catEntries) {
 99→      const title = entry.title ? String(entry.title) : entry.id;
100→      const compact = entry.content.replace(/\s+/g, ' ').trim();
101→      const summary = compact.length > 280 ? `${compact.slice(0, 277)}...` : compact;
102→      const line = `- [${title}] ${summary}`;
103→
104→      if (catChars + line.length + 1 > perCatBudget) {
105→        catTruncated = true;
106→        break;
107→      }
108→      catLines.push(line);
109→      catChars += line.length + 1;
110→      shown++;
111→    }
112→
113→    if (catTruncated) {
114→      catLines.push(`...(${cat}: showing ${shown}/${catEntries.length}, budget-capped)`);
115→    }
116→    blocks.push(catLines.join('\n'));
117→  }
118→
119→  return blocks.join('\n\n').trimEnd();
120→}
121→
122→// ─────────────────────────────────────────────
123→// M3-C: run-end DataRequest sedimentation
124→// ─────────────────────────────────────────────
125→
126→function normalizeForStableId(text: string): string {
127→  return text.replace(/\s+/g, ' ').trim().toLowerCase();
128→}
129→
130→/**
131→

460→      type: 'section-layout-chaos',
461→      benchmarkRef: 'v5.3 §0-§7 八章节骨架',
462→      lessonText: `runId=${runId} 的 sections heading 都不含 §X 章节号（v5.3 标杆是 §0-§7 八章节）。修法：narrative LLM 按 {{REPORT_TEMPLATE}} 注入的模板章节骨架组织 sections，每个 section 的 heading 以 §X 开头（如 "§0 结论先行：..." / "§1 采集元信息：..."）。render 层会按 heading 模糊匹配合并视觉资产到对应 §X section。`,
463→    });
464→  }
465→
466→  return { gaps };
467→}
468→
469→// ──────────────────────────────── 主入口 ────────────────────────────────
470→
471→export async function runPrismNarrative(
472→  opts: RunPrismNarrativeOpts = {},
473→): Promise<NarrativeRunResult> {
474→  const source = opts.source ?? 'unity';
475→  const runId = opts.runId ?? (source === 'perfetto' ? 'bk26b-perfetto-triad' : 'unity-outside-stressmove');
476→  const config = getConfig();
477→
478→  // Resolve outputDir（含 findings.json + verdict.json）
479→  const repoRoot = path.resolve(__dirname, '../../..');
480→  const outputDir = opts.outputDir
481→    ? path.resolve(repoRoot, opts.outputDir)
482→    : path.join(repoRoot, 'web', 'data', 'prism-out', runId);
483→
484→  const narrativePath = path.join(outputDir, 'narrative.json');
485→  const findingsPath = path.join(outputDir, 'findings.json');
486→  const verdictPath = path.join(outputDir, 'verdict.json');
487→
488→  // 前置检查：findings.json + verdict.json 必须存在
489→  if (!fs.existsSync(findingsPath)) {
490→    return makeNarrativeError(runId, outputDir, narrativePath,
491→      `findings.json not found: ${findingsPath}. Run explore stage first (runPrismExplore).`);
492→  }
493→  if (!fs.existsSync(verdictPath)) {
494→    return makeNarrativeError(runId, outputDir, narrativePath,
495→      `verdict.json not found: ${verdictPath}. Run explore stage first (runPrismExplore).`);
496→  }
497→
498→  // 加载并替换 narrative-prompt.txt（数据源无关）
499→  const promptTemplatePath = path.join(__dirname, 'prompts', 'narrative-prompt.txt');
500→  if (!fs.existsSync(promptTemplatePath)) {
501→    return makeNarrativeError(runId, outputDir, narrativePath,
502→      `narrative-prompt.txt not found: ${promptTemplatePath}`);
503→  }
504→
505→  let promptText = fs.readFileSync(promptTemplatePath, 'utf-8');
506→  const outputDirPosix = toPosix(outputDir);
507→  promptText = promptText.replace(/\{\{OUTPUT_DIR\}\}/g, outputDirPosix);
508→  promptText = promptText.replace(/\{\{RUN_ID\}\}/g, runId);
509→  // DR-44 §3.2: {{REPORT_TEMPLATE}} 按数据源注入章节模板（WT-028 填，本阶段为空）
510→  const reportTemplate = resolveReportTemplate(source, outputDir, runId);
511→  promptText = promptText.replace(/\{\{REPORT_TEMPLATE\}\}/g, reportTemplate);
512→  // WT-034: {{MEMORY_INJECTION}} 注入 lessons 回路（对称 explore-service.ts:711）
513→  // 沉淀历次 narrative 红队复扫的写作缺口教训，让本次写作吸收历史经验
514→  promptText = promptText.replace(/\{\{MEMORY_INJECTION\}\}/g, formatMemoryForPrompt());
515→
516→  // Resolve CLI
517→  const provider = opts.cliProvider ?? 'codebuddy';
518→  const { command: cliCommand, resolved } = resolveCliExecutable(provider, config.cliPaths?.[provider]);
519→
