 76→// ─────────────────────── WT-037 辅助函数 ───────────────────────
 77→// 视觉资产 schema 兼容期：WT-036 后视觉资产在 sections[].items[].visualAsset，
 78→// 但历史 narrative.json（v1/v4 标杆）仍是旧 schema（顶层 metaInfo/threadOverview/throttlingMatrix/redlineMatrix/asciiArt）。
 79→// 辅助函数同时扫新 schema (item.visualAsset) 和旧 schema (顶层字段)，兼容期双向都扫。
 80→
 81→/**
 82→ * 在 sections[].items[].visualAsset 里按 title 正则找视觉资产（新 schema）。
 83→ * 旧 schema 没有这个字段，返回 undefined（由调用方回退到顶层字段）。
 84→ */
 85→function findVisualAssetByTitle(narrative: NarrativeReport, titleRe: RegExp): VisualAsset | undefined {
 86→  for (const sec of narrative.sections) {
 87→    for (const item of sec.items) {
 88→      if (item.visualAsset && titleRe.test(item.visualAsset.title)) {
 89→        return item.visualAsset;
 90→      }
 91→    }
 92→  }
 93→  return undefined;
 94→}
 95→
 96→/**
 97→ * 按统计视觉资产数量（新 schema：扫 sections[].items[].visualAsset.type）。
 98→ * 旧 schema 没有 type 字段，扫不到（由调用方回退到顶层字段）。
 99→ */
100→function countVisualAssetsByType(narrative: NarrativeReport, type: 'table' | 'ascii' | 'matrix'): number {
101→  let n = 0;
102→  for (const sec of narrative.sections) {
103→    for (const item of sec.items) {
104→      if (item.visualAsset?.type === type) n++;
105→    }
106→  }
107→  return n;
108→}
109→
110→/**
111→ * 简单文本相似度（Jaccard on tokens），不引外部库。
112→ * 用于 D1 检查 topConclusions.problem 与 §0 item.title 是否高度重复。
113→ */
114→function textSimilarity(a: string, b: string): number {
115→  const tokensA = new Set(a.split(/[\s,，。；;:：()（）/\\]+/).filter(t => t.length > 1));
116→  const tokensB = new Set(b.split(/[\s,，。；;:：()（）/\\]+/).filter(t => t.length > 1));
117→  const intersection = [...tokensA].filter(t => tokensB.has(t)).length;
118→  const union = new Set([...tokensA, ...tokensB]).size;
119→  return union > 0 ? intersection / union : 0;
120→}
121→
122→/**
123→ * 旧 schema 兼容：从顶层字段读视觉资产行数。
124→ * WT-036 前视觉资产在顶层 metaInfo/threadOverview/throttlingMatrix/redlineMatrix/asciiArt。
125→ * 新 schema 这些字段不在 NarrativeReport 类型里，用 any 取。
126→ */
127→function getLegacyTopLevelField(narrative: NarrativeReport, field: string): unknown {
128→  return (narrative as unknown as Record<string, unknown>)[field];
129→}
130→
131→/**
132→ * 兼容期统一取"ASCII 图数量"——先扫新 schema (item.visualAsset.type==='ascii')，
133→ * 回退到旧 schema 顶层 asciiArt 数组 + topConclusions[].asciiArt。
134→ */
135→function countAsciiArtCompat(narrative: NarrativeReport): { count: number; source: 'new-schema' | 'legacy' | 'missing' } {
136→  // 新 schema
137→  const n = countVisualAssetsByType(narrative, 'ascii');
138→  if (n > 0) return { count: n, source: 'new-schema' };
139→  // 旧 schema：顶层 asciiArt 数组 + topConclusions 挂的 asciiArt
140→  const legacy = getLegacyTopLevelField(narrative, 'asciiArt');
141→  let count = 0;
142→  if (Array.isArray(legacy)) count += legacy.length;
143→  for (const tc of narrative.topConclusions ?? []) {
144→    if (tc.asciiArt) count++;
145→  }
146→  return count > 0 ? { count, source: 'legacy' } : { count: 0, source: 'missing' };
147→}
