660→        // 用正则抓所有"数字.数字"或"数字→数字"或"数字→数字"模式，过滤掉太常见的（如 0, 1, 16.66 帧预算）
661→        const extractNumericFeatures = (text: string): Set<string> => {
662→          const features = new Set<string>();
663→          // foldChange 模式：×N.N 或 X.NN 倍
664→          const foldChangeMatches = text.match(/×\d+(?:\.\d+)?|\d+(?:\.\d+)?\s*倍/g) || [];
665→          for (const m of foldChangeMatches) features.add(m);
666→          // ms 数字模式：N.NNms（含 0.069, 3.994 等）
667→          const msMatches = text.match(/\d+(?:\.\d+)?\s*ms/g) || [];
668→          for (const m of msMatches) features.add(m);
669→          // GC alloc 数字：N→N 或 N → N（含 14043 等）
670→          const gcMatches = text.match(/GC\s*alloc\s*\d+(?:\.\d+)?/gi) || [];
671→          for (const m of gcMatches) features.add(m.toLowerCase());
672→          // 箭头数字模式：N.NN→N.NN 或 N.NN → N.NN（含 0.069→3.994 等）
673→          const arrowMatches = text.match(/\d+(?:\.\d+)?\s*[→→]\s*\d+(?:\.\d+)?/g) || [];
674→          for (const m of arrowMatches) features.add(m.replace(/\s+/g, ''));
675→          // 过滤太常见的数字（帧预算 16.66/33.33，0/1 这种）
676→          for (const common of ['16.66ms', '33.33ms', '0ms', '1ms', '×0', '×1', '×2', '0倍', '1倍', '2倍']) {
677→            features.delete(common);
678→          }
679→          return features;
680→        };
