688→          for (let j = 0; j < drilldownItems.length; j++) {
689→            const ddItem = drilldownItems[j];
690→            const ddText = `${ddItem.title} ${ddItem.narrative ?? ''}`;
691→            const ddFeatures = extractNumericFeatures(ddText);
692→            const shared = [...s0Features].filter(f => ddFeatures.has(f));
693→            // 阈值 ≥2：§0 和 §3 下钻共享 ≥2 个数字特征串 = 内容重复
694→            if (shared.length >= 2) {
695→              dr49Violation = {
696→                section0Idx: i + 1,
697→                drilldownIdx: j + 1,
698→                sharedFeatures: shared,
699→                section0Title: s0Item.title,
700→                drilldownTitle: ddItem.title,
701→              };
702→              break;
703→            }
704→          }
705→          if (dr49Violation) break;
706→        }
707→        assert(!dr49Violation, '§0 与 §3 下钻 narrative 内容不重复（共享数字特征串 <2）', {
708→          ...(dr49Violation ?? {}),
709→          hint: '§0 应是父模块级摘要（涨 X 倍 + 占 p50 Y%），§3 下钻才讲子节点细节（具体 ms/GC alloc 数字）。§0 讲子节点具体数字 = 和 §3 下钻内容重复——DR-49 教训：prompt 约束只禁形式不禁内容，LLM 换形式绕过',
710→        });
711→      } else {
712→        console.log('  SKIP: 没找到 §0 或 §3 section');
713→      }
714→
715→
716→      // ── 3. report.html 视觉资产检查 ──
717→      console.log('\n[3] report.html 视觉资产（DR-41 五条硬规则 + 模板要求）');
718→
719→      if (!fs.existsSync(reportHtmlPath)) {
720→        assert(false, 'report.html 存在', { path: reportHtmlPath });
721→      } else {
722→        const html = fs.readFileSync(reportHtmlPath, 'utf-8');
723→
724→        // 3a. 调用树渲染（不是全 fallback）
725→        const fallbackCount = (html.match(/tree-section fallback/g) || []).length;
726→        // 真实树 = 含 tree-section class 但不含 fallback 的 div
727→        const allTreeSections = (html.match(/class="tree-section[^"]*"/g) || []).length;
728→        const realTreeCount = allTreeSections - fallbackCount;
729→        assert(realTreeCount > 0, `report.html 有真实调用树渲染 (>=1 棵，非全 fallback)`, { realTrees: realTreeCount, fallbacks: fallbackCount });
730→
731→        // 3b. 核心结论表
732→        assert(html.includes('top-conclusions'), 'report.html 含核心结论表');
733→        assert(html.includes('tc-rank'), '核心结论表有 rank 列');
734→
735→        // 3c. 已排除项（ruledOut，超越作文机的辨伪能力）
736→        assert(html.includes('ruled-out'), 'report.html 含已排除项（ruledOut）');
737→
738→        // 3d. 优化优先级表
739→        assert(html.includes('priority-table'), 'report.html 含优化优先级表');
740→
741→        // 3e. 严重度标注
742→        assert(html.includes('sev-dot') || html.includes('sev-chip'), 'report.html 含严重度标注');
743→
744→        // 3f. provenance 校验痕迹（render-html 的 DR-44 A2 校验通过了才会产出 html）
745→        assert(html.includes('Prism render-html') || html.includes('render-html'), 'report.html 由 render-html 产出');
746→
747→        // 3g. 无审计字段泄漏到 HTML
748→        assert(!html.includes('evidenceIds'), 'report.html 无 evidenceIds 泄漏');
749→        assert(!html.includes('selfCritique'), 'report.html 无 selfCritique 泄漏');
750→
751→        // 3h. 文件大小（太小说明内容单薄）
752→        const sizeKB = fs.statSync(reportHtmlPath).size / 1024;
753→        if (sizeKB < 20) {
754→          warn(`report.html 偏小 (${sizeKB.toFixed(1)} KB)`, {
755→            hint: 'v5.3 标杆报告内容充实，<20KB 可能内容单薄或缺视觉资产',
756→          });
757→        } else {
758→          assert(true, `report.html 大小合理 (${sizeKB.toFixed(1)} KB)`);
759→        }
760→
761→        // 3i. WT-045: 每棵 callTree 的 tree-row 数 ≤ 200（防巨长调用树，剪枝生效检查）
762→        //   按 <div class="tree-section" 或 <div class="tc-tree-section" 分割成多棵 callTree，
763→        //   每棵内数 class="tree-row" 的数量，任一棵 > 200 = FAIL。
764→        //   阈值 200 是宽松阈值：perfetto 每棵约 30-50 节点，unity 剪枝后预期 50-100 节点。
765→        //   抓"完全没剪枝"的退化（如 4695 行那种）。
766→        const treeRowMatches = html.match(/class="tree-row[^"]*"/g) || [];
767→        const totalTreeRows = treeRowMatches.length;
768→        // 按 tree-section / tc-tree-section 分割（topConclusions 挂的 callTree 用 tc-tree-section）
769→        // 简化实现：用 indexOf 顺序扫，统计每棵树内的 tree-row 数
770→        const treeStartRegex = /<div class="(tree-section|tc-tree-section)[^"]*"/g;
771→        const treeRowsPerTree: number[] = [];
772→        let lastStartIdx = -1;
773→        let m: RegExpExecArray | null;
774→        while ((m = treeStartRegex.exec(html)) !== null) {
775→          if (lastStartIdx >= 0) {
776→            // 上一棵树的范围 = [lastStartIdx, m.index)，数其中的 tree-row 数
777→            const segment = html.slice(lastStartIdx, m.index);
778→            const cnt = (segment.match(/class="tree-row[^"]*"/g) || []).length;
779→            treeRowsPerTree.push(cnt);
780→          }
781→          lastStartIdx = m.index;
782→        }
783→        if (lastStartIdx >= 0) {
784→          // 最后一棵树到文件尾
785→          const segment = html.slice(lastStartIdx);
786→          const cnt = (segment.match(/class="tree-row[^"]*"/g) || []).length;
787→          treeRowsPerTree.push(cnt);
788→        }
789→        const maxTreeRows = treeRowsPerTree.length > 0 ? Math.max(...treeRowsPerTree) : 0;
790→        assert(
791→          maxTreeRows <= 200,
792→          `每棵 callTree 的 tree-row 数 ≤ 200（防巨长调用树，WT-045）`,
793→          { maxTreeRows, threshold: 200, trees: treeRowsPerTree.length, totalTreeRows },
794→        );
795→      }
796→    }
797→  }
798→} else {
799→  console.log('\n[2] narrative.json 结构契约 — SKIP（未传 --dir）');
800→  console.log('[3] report.html 视觉资产 — SKIP（未传 --dir）');
801→  console.log('    提示：加 --dir data/prism-out/<run> 跑完整检查');
802→}
